"""Generate static zsh completion from the CLI's argparse declarations."""

from __future__ import annotations

import argparse
import shlex


def _escape(text: str) -> str:
    """Escape _arguments syntax before quoting the enclosing shell word."""
    for character in ("\\", ":", "[", "]"):
        text = text.replace(character, "\\" + character)
    return text


def _value_completion(action: argparse.Action) -> str:
    if action.choices is not None:
        return "(" + " ".join(shlex.quote(str(value)) for value in action.choices) + ")"
    if "--report-dir" in action.option_strings:
        return "_files -/"
    if action.metavar in {"PATH", "FILE", "SOURCE"}:
        return "_files"
    return "_guard '[^-]*' " + shlex.quote(str(action.metavar or action.dest))


def _parser_function(parser: argparse.ArgumentParser, name: str) -> str:
    specs = []
    children = {}
    multiple_values = {}
    position = 0
    for action in parser._actions:
        if action.help == argparse.SUPPRESS:
            continue
        if isinstance(action, argparse._SubParsersAction):
            children = action.choices
            specs.extend([":子命令:(" + " ".join(children) + ")", "*::参数:->command"])
            continue
        description = _escape(action.help or action.dest)
        value = _escape(str(action.metavar or action.dest)) + ":" + _value_completion(action)
        if action.option_strings:
            for option in action.option_strings:
                # argparse accepts repeated options; custom DSL/forward actions also accumulate them.
                spec = "*" + option + ("=" if action.nargs != 0 and option.startswith("--") else "")
                spec += "[" + description + "]"
                if action.nargs != 0:
                    spec += ":" + value
                    if action.nargs in ("+", "*"):
                        multiple_values[option] = _value_completion(action)
                specs.append(spec)
        else:
            position += 1
            specs.append(str(position) + ("::" if action.nargs == "?" else ":") + value)
    if multiple_values:
        # A zsh variadic option consumes later flags too; use positional values
        # only while the most recent option is still the variadic one.
        specs.append("*:额外参数:->values")
    lines = [f"{name}() {{", "  local context state state_descr line", "  local -A opt_args", "  local curcontext=$curcontext", "  _arguments -s -S -C \\"]
    lines.append(" \\\n".join("    " + shlex.quote(spec) for spec in specs))
    if children:
        lines.extend(['  if [[ $state == command ]]; then', '    case $line[1] in'])
        for command in children:
            child_name = name + "_" + command.replace("-", "_")
            lines.append(f"      {shlex.quote(command)}) {child_name} ;;")
        lines.extend(["    esac", "  fi"])
    if multiple_values:
        lines.extend(['  if [[ $state == values ]]; then', '    local -a previous_options', '    previous_options=( ${(M)words[1,CURRENT-1]:#-*} )', '    case $previous_options[-1] in'])
        for option, completion in multiple_values.items():
            lines.append(f"      {shlex.quote(option)}) {completion} ;;")
        lines.extend(["    esac", "  fi"])
    lines.append("}")
    for command, child in children.items():
        lines.append(_parser_function(child, name + "_" + command.replace("-", "_")))
    return "\n".join(lines)


def zsh_completion(parser: argparse.ArgumentParser) -> str:
    return (
        "# Generated by ydf-browser completion zsh.\n"
        "if (( ! $+functions[compdef] )); then\n"
        "  autoload -Uz compinit\n"
        "  compinit || return $?\n"
        "fi\n"
        + _parser_function(parser, "_ydf_browser")
        + "\ncompdef _ydf_browser ydf-browser\n"
    )
